                view = tx[conn]
            else:
                view = committed
            existed = key in view
            direct = 0
            inserted = False
            if is_put:
                if existed:
                    if put_mode == "ignore":
                        direct = 0
                    elif put_mode == "replace":
                        view[key] = value
                        direct = 1
                        inserted = True
                    else:
                        view[key] = value
                        direct = 1
                        inserted = False
                else:
                    view[key] = value
                    direct = 1
                    inserted = True
            else:
                if existed:
                    view[key] = value
                    direct = 1
                else:
                    direct = 0
